SELECT 'insight_reports' AS t, COUNT(*) AS n, MIN(as_of) AS first_as_of, MAX(as_of) AS last_as_of, COUNT(*) FILTER (WHERE ticker IN ('SPY','QQQ','IWM')) AS n_3tickers, COUNT(*) FILTER (WHERE report->'level_basis' IS NOT NULL AND jsonb_typeof(report->'level_basis') = 'object') AS n_with_level_basis FROM insight_reports;
SELECT 'insight_reports_history' AS t, COUNT(*) AS n, MIN(as_of) AS first_as_of, MAX(as_of) AS last_as_of FROM insight_reports_history;
SELECT 'insight_runs' AS t, COUNT(*) AS n, MIN(created_at) AS first_created, MAX(created_at) AS last_created FROM insight_runs;
SELECT ticker, (ts AT TIME ZONE 'America/New_York')::date AS session_et, to_char(ts AT TIME ZONE 'America/New_York', 'HH24:MI') AS et, open, high, low, close, volume FROM market_data_intraday WHERE ticker = 'SPY' AND interval = '1min' AND (ts AT TIME ZONE 'America/New_York')::date = DATE '2026-11-10' AND (ts AT TIME ZONE 'America/New_York')::time IN (TIME '09:28', TIME '09:29', TIME '09:30', TIME '09:31', TIME '09:32', TIME '15:58', TIME '15:59', TIME '16:00', TIME '16:01') ORDER BY ts;
SELECT ticker, date, open, high, low, close, atr_14, pre_high, pre_low, gap_pct FROM market_data_daily WHERE ticker IN ('SPY','QQQ','IWM') AND date BETWEEN DATE '2026-11-06' AND DATE '2026-11-11' ORDER BY date, ticker;
SELECT ticker, (ts AT TIME ZONE 'America/New_York')::date AS session_et, MIN(to_char(ts AT TIME ZONE 'America/New_York', 'HH24:MI')) AS first_et, MAX(to_char(ts AT TIME ZONE 'America/New_York', 'HH24:MI')) AS last_et, COUNT(*) AS bars, COUNT(*) FILTER (WHERE (ts AT TIME ZONE 'America/New_York')::time >= TIME '09:30' AND (ts AT TIME ZONE 'America/New_York')::time < TIME '16:00') AS rth_bars, MAX(data_source) AS src FROM market_data_intraday WHERE ticker IN ('SPY','QQQ','IWM') AND interval = '1min' AND ts >= TIMESTAMPTZ '2026-10-23 00:00:00+00' GROUP BY 1, 2 ORDER BY 2, 1;
